-- CargoHub PostgreSQL schema. Source field names are preserved.
-- Run in an empty schema; existing tables are never deleted or overwritten.
CREATE SCHEMA cargohub;

CREATE TABLE cargohub."warehouse" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" text NOT NULL,
    "name" text NOT NULL,
    "address" text NOT NULL,
    "city" text NOT NULL,
    "zip_code" text NOT NULL,
    "province" text NOT NULL,
    "country" text NOT NULL,
    "contact_name" text NOT NULL,
    "contact_phone" text NOT NULL,
    "contact_email" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("code")
);

CREATE TABLE cargohub."client" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" text NOT NULL,
    "address" text NOT NULL,
    "city" text NOT NULL,
    "zip_code" text NOT NULL,
    "province" text NOT NULL,
    "country" text NOT NULL,
    "contact_name" text NOT NULL,
    "contact_phone" text NOT NULL,
    "contact_email" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE cargohub."supplier" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" text NOT NULL,
    "name" text NOT NULL,
    "address" text NOT NULL,
    "city" text NOT NULL,
    "zip_code" text NOT NULL,
    "province" text NOT NULL,
    "country" text NOT NULL,
    "contact_name" text NOT NULL,
    "phone_number" text NOT NULL,
    "reference" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    UNIQUE ("code")
);

CREATE TABLE cargohub."item_line" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" text NOT NULL,
    "description" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE cargohub."item_group" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" text NOT NULL,
    "description" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE cargohub."item_type" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" text NOT NULL,
    "description" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE cargohub."location" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "code" text NOT NULL,
    "name" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("warehouse_id") REFERENCES cargohub."warehouse" (id) ON DELETE RESTRICT
);

CREATE TABLE cargohub."item" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "code" text NOT NULL,
    "description" text NOT NULL,
    "barcode" text NOT NULL,
    "model_number" text NOT NULL,
    "commodity_code" bigint NOT NULL,
    "unit_weight" numeric NOT NULL,
    "item_line_id" bigint NOT NULL,
    "item_group_id" bigint NOT NULL,
    "item_type_id" bigint NOT NULL,
    "min_purchase_qty" bigint NOT NULL,
    "case_size" bigint NOT NULL,
    "packaging_type" text NOT NULL,
    "order_multiple" bigint NOT NULL,
    "supplier_id" bigint NOT NULL,
    "supplier_sku" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("supplier_id") REFERENCES cargohub."supplier" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("item_line_id") REFERENCES cargohub."item_line" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("item_group_id") REFERENCES cargohub."item_group" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("item_type_id") REFERENCES cargohub."item_type" (id) ON DELETE RESTRICT,
    UNIQUE ("code"),
    UNIQUE ("barcode"),
    CHECK ("unit_weight" >= 0),
    CHECK ("min_purchase_qty" > 0),
    CHECK ("case_size" > 0),
    CHECK ("order_multiple" > 0)
);

CREATE TABLE cargohub."inventory" (
    "item_id" bigint NOT NULL,
    "location_id" bigint NOT NULL,
    "quantity_on_hand" bigint NOT NULL,
    "quantity_expected" bigint NOT NULL,
    "quantity_ordered" bigint NOT NULL,
    "quantity_allocated" bigint NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("item_id", "location_id"),
    FOREIGN KEY ("item_id") REFERENCES cargohub."item" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("location_id") REFERENCES cargohub."location" (id) ON DELETE RESTRICT,
    CHECK ("quantity_on_hand" >= 0),
    CHECK ("quantity_expected" >= 0),
    CHECK ("quantity_ordered" >= 0),
    CHECK ("quantity_allocated" >= 0)
);

CREATE TABLE cargohub."order" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "client_id" bigint NOT NULL,
    "order_date" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "request_date" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "reference" text NOT NULL,
    "customer_po_number" text NOT NULL,
    "order_status" text NOT NULL,
    "shipping_notes" text,
    "warehouse_id" bigint NOT NULL,
    "ship_to_client_id" bigint NOT NULL,
    "bill_to_client_id" bigint NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("client_id") REFERENCES cargohub."client" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("ship_to_client_id") REFERENCES cargohub."client" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("bill_to_client_id") REFERENCES cargohub."client" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("warehouse_id") REFERENCES cargohub."warehouse" (id) ON DELETE RESTRICT
);

CREATE TABLE cargohub."order_item" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "order_id" bigint NOT NULL,
    "item_id" bigint NOT NULL,
    "amount" bigint NOT NULL,
    "unit_price" numeric NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("order_id") REFERENCES cargohub."order" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("item_id") REFERENCES cargohub."item" (id) ON DELETE RESTRICT,
    CHECK ("amount" > 0),
    CHECK ("unit_price" >= 0)
);

CREATE TABLE cargohub."shipment" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "reference" text NOT NULL,
    "order_id" bigint NOT NULL,
    "shipment_date" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "shipment_type" text NOT NULL,
    "shipment_status" text NOT NULL,
    "carrier_name" text NOT NULL,
    "shipping_method" text NOT NULL,
    "payment_type" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("order_id") REFERENCES cargohub."order" (id) ON DELETE RESTRICT,
    UNIQUE ("reference")
);

CREATE TABLE cargohub."shipment_item" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "shipment_id" bigint NOT NULL,
    "item_id" bigint NOT NULL,
    "amount" bigint NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("shipment_id") REFERENCES cargohub."shipment" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("item_id") REFERENCES cargohub."item" (id) ON DELETE RESTRICT,
    CHECK ("amount" > 0)
);

CREATE TABLE cargohub."transfer" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "reference" text NOT NULL,
    "from_location_id" bigint NOT NULL,
    "to_location_id" bigint NOT NULL,
    "transfer_status" text NOT NULL,
    "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("from_location_id") REFERENCES cargohub."location" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("to_location_id") REFERENCES cargohub."location" (id) ON DELETE RESTRICT,
    UNIQUE ("reference"),
    CHECK (from_location_id <> to_location_id)
);

CREATE TABLE cargohub."transfer_item" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "transfer_id" bigint NOT NULL,
    "item_id" bigint NOT NULL,
    "amount" bigint NOT NULL,
    PRIMARY KEY ("id"),
    FOREIGN KEY ("transfer_id") REFERENCES cargohub."transfer" (id) ON DELETE RESTRICT,
    FOREIGN KEY ("item_id") REFERENCES cargohub."item" (id) ON DELETE RESTRICT,
    CHECK ("amount" > 0)
);

CREATE TABLE cargohub."user" (
    "api_key" text NOT NULL,
    "app" text NOT NULL,
    "endpoint_access" jsonb NOT NULL,
    PRIMARY KEY ("app"),
    UNIQUE ("api_key"),
    CHECK (jsonb_typeof(endpoint_access) = 'object')
);

CREATE INDEX "ix_location_warehouse_id" ON cargohub."location" ("warehouse_id");
CREATE INDEX "ix_item_supplier_id" ON cargohub."item" ("supplier_id");
CREATE INDEX "ix_item_item_line_id" ON cargohub."item" ("item_line_id");
CREATE INDEX "ix_item_item_group_id" ON cargohub."item" ("item_group_id");
CREATE INDEX "ix_item_item_type_id" ON cargohub."item" ("item_type_id");
CREATE INDEX "ix_inventory_location_id" ON cargohub."inventory" ("location_id");
CREATE INDEX "ix_order_client_id" ON cargohub."order" ("client_id");
CREATE INDEX "ix_order_ship_to_client_id" ON cargohub."order" ("ship_to_client_id");
CREATE INDEX "ix_order_bill_to_client_id" ON cargohub."order" ("bill_to_client_id");
CREATE INDEX "ix_order_warehouse_id" ON cargohub."order" ("warehouse_id");
CREATE INDEX "ix_order_item_order_id" ON cargohub."order_item" ("order_id");
CREATE INDEX "ix_order_item_item_id" ON cargohub."order_item" ("item_id");
CREATE INDEX "ix_shipment_order_id" ON cargohub."shipment" ("order_id");
CREATE INDEX "ix_shipment_item_shipment_id" ON cargohub."shipment_item" ("shipment_id");
CREATE INDEX "ix_shipment_item_item_id" ON cargohub."shipment_item" ("item_id");
CREATE INDEX "ix_transfer_from_location_id" ON cargohub."transfer" ("from_location_id");
CREATE INDEX "ix_transfer_to_location_id" ON cargohub."transfer" ("to_location_id");
CREATE INDEX "ix_transfer_item_transfer_id" ON cargohub."transfer_item" ("transfer_id");
CREATE INDEX "ix_transfer_item_item_id" ON cargohub."transfer_item" ("item_id");
CREATE INDEX ix_order_reference ON cargohub."order" (reference);
CREATE INDEX ix_location_code ON cargohub."location" (code);

-- Several shipments may reference the same order; order_id is not unique.
-- Application code must set updated_at when modifying records.
